mapper.update:
UPDATE kb_chat_message
   SET status = 'FAILED', error_message = #{message}, completed_at = NOW()
 WHERE id = #{messageId} AND conversation_id = #{conversationId}

mapper.select:
SELECT id, sequence_no AS "sequenceNo", role, content, status, source_kb_ids AS "sourceKbIdsRaw", retrieved_chunk_ids AS "retrievedChunkIdsRaw", model_name AS "modelName", latency_ms AS "latencyMs", error_message AS "errorMessage", qa_record_id AS "qaRecordId", created_at AS "createdAt", completed_at AS "completedAt" FROM kb_chat_message WHERE conversation_id = #{conversationId}
AND sequence_no < #{beforeSequence}
ORDER BY sequence_no DESC LIMIT #{limit}
